<?php
declare(strict_types=1);
require_once __DIR__.'/includes/certificate-auth.php';
$user=fleet_cert_user();
if(!$user){header('Location: login.php',true,302);exit;}
if(!in_array('APP_CONTROLLER',$user['roles']??[],true)){if(empty($user['roles']))header('Location: welcome.php',true,302);else header('Location: index.php',true,302);exit;}
?>
