(()=>{const $=s=>document.querySelector(s),msg=$('#message');let setup=false;async function req(data){const r=await fetch('api/controller-otp.php',{method:data?'POST':'GET',credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Content-Type':'application/json'},body:data?JSON.stringify(data):undefined,cache:'no-store'});const d=await r.json();if(!r.ok||!d.ok)throw Error(d.message||'Verification failed.');return d}async function load(){try{const d=await req();setup=!d.enrolled;$('#setup').hidden=!setup;$('#verify').hidden=false;$('#codeLabel').textContent=setup?'Enter the code to finish setup':'Authenticator code';$('#submit').disabled=setup;if(!setup)$('#submit').disabled=false}catch(e){msg.className='error';msg.textContent=e.message}}$('#begin').onclick=async()=>{const b=$('#begin');b.disabled=true;msg.className='';msg.textContent='Creating a new authenticator QR code…';try{const d=await req({action:'begin'});$('#secret').textContent=d.secret;const qr=qrcode(0,'M');qr.addData(d.otpauth_uri,'Byte');qr.make();$('#otpQr').innerHTML=qr.createSvgTag(5,4,'Authenticator setup QR code','Scan this QR code using your authenticator app');$('#otpQrWrap').hidden=false;$('#submit').disabled=false;msg.textContent='Scan the QR code, then enter the current six-digit code to finish setup.';$('#code').focus()}catch(e){$('#otpQrWrap').hidden=true;msg.className='error';msg.textContent=e.message||'The QR code could not be created. You can use the manual setup key instead.';$('#submit').disabled=false}finally{b.disabled=false}};$('#submit').onclick=async()=>{const b=$('#submit');b.disabled=true;msg.className='';try{const d=await req({action:setup?'verify_setup':'verify',code:$('#code').value});msg.className='success';msg.textContent=d.message;location.replace(d.redirect)}catch(e){msg.className='error';msg.textContent=e.message;b.disabled=false}};$('#logout').onclick=async()=>{try{await fetch('api/certificate-auth.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({action:'logout'})})}finally{location.replace('login.php')}};load()})();
